mapper.update:
UPDATE setmeal
category_id = #{categoryId}, name = #{name}, price = #{price}, image = #{image}, description = #{description}, status = #{status}, update_time = #{updateTime}, update_user = #{updateUser},
WHERE id = #{id}

mapper.select:
SELECT * FROM setmeal

    AND name LIKE CONCAT('%', #{name}, '%')
    AND category_id = #{categoryId}
    AND status = #{status}

ORDER BY create_time DESC
